const item = $input.first();
const form = item.json || {};
const binary = item.binary || {};

const category = form['Product Category'] || 'Area Rug';
const focus = form['Focus Area'] || '';

let p2Content = '';
let p3Content = '';

const binaryKeys = Object.keys(binary);

// Identify P2 and P3 keys dynamically
const p2Key = binaryKeys.find(k => k.toUpperCase().includes('P2') || k.toUpperCase().includes('MARKET')) || binaryKeys[0];
const p3Key = binaryKeys.find(k => (k.toUpperCase().includes('P3') || k.toUpperCase().includes('COMPETITOR')) && k !== p2Key) || binaryKeys[1];

// Safely pull the true binary buffer using n8n's official helper
if (p2Key && binary[p2Key]) {
  try {
    const buf = await this.helpers.getBinaryDataBuffer(0, p2Key);
    // Microsoft Edge HTML files use UTF-16 LE encoding; check for null bytes or BOM
    p2Content = (buf.includes(0x00) || (buf.length > 1 && buf[0] === 0xFF)) 
      ? buf.toString('utf16le') 
      : buf.toString('utf8');
  } catch (e) {
    console.log("P2 buffer error:", e.message);
  }
}

if (p3Key && binary[p3Key]) {
  try {
    const buf = await this.helpers.getBinaryDataBuffer(0, p3Key);
    p3Content = (buf.includes(0x00) || (buf.length > 1 && buf[0] === 0xFF)) 
      ? buf.toString('utf16le') 
      : buf.toString('utf8');
  } catch (e) {
    console.log("P3 buffer error:", e.message);
  }
}

// Convert HTML to a readable outline: headings become "## ...", table rows become "a | b | c"
const toOutline = (html) => String(html)
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<img[^>]*>/gi, '')
  .replace(/<\/tr>/gi, '\n')
  .replace(/<\/t[dh]>/gi, ' | ')
  .replace(/<h([1-4])[^>]*>/gi, (m, n) => '\n' + '#'.repeat(Number(n)) + ' ')
  .replace(/<\/(p|li|div|h[1-4]|ul|table|section)>/gi, '\n')
  .replace(/<[^>]+>/g, '')
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n\s*\n+/g, '\n')
  .trim();

// Limits are generous on purpose: typical P2 + P3 reports are about 6k tokens combined.
// Keep llama-server context (-c) at roughly 16k per slot.
const P2_LIMIT = 14000;
const P3_LIMIT = 18000;

const p2Full = toOutline(p2Content);
const p3Full = toOutline(p3Content);

return [{
  json: {
    category,
    focus,
    p2_content: p2Full.slice(0, P2_LIMIT),
    p3_content: p3Full.slice(0, P3_LIMIT),
    p2_chars: p2Full.length,
    p3_chars: p3Full.length,
    p2_truncated: p2Full.length > P2_LIMIT,
    p3_truncated: p3Full.length > P3_LIMIT
  }
}];

// Merges the core response (Call LLM) with the extended response (Call LLM Extended).
// A failure in the extended call never damages the core report.
const arr = v => (Array.isArray(v) ? v : []);

const FALLBACK = {
  key_metrics: [],
  data_foundation: { p2_insights: [], p3_insights: [] },
  executive_summary: 'The model output could not be parsed, so no strategy was generated for this run. See the run notes at the bottom of this report.',
  content_ideas: [],
  social_captions: { instagram: [], pinterest: [], facebook: [], tiktok: [] },
  campaigns: [],
  email_subjects: [],
  competitive_angles: [],
  content_priorities: []
};

const extractText = (raw) => {
  if (!raw) return '';
  if (raw.choices && raw.choices[0] && raw.choices[0].message && raw.choices[0].message.content) return raw.choices[0].message.content;
  if (raw.message && raw.message.content) return raw.message.content;
  if (raw.text) return raw.text;
  if (raw.output) return raw.output;
  return '';
};

const parseJson = (text) => {
  let s = String(text || '').replace(/```json/gi, '').replace(/```/g, '').trim();
  const a = s.indexOf('{');
  const b = s.lastIndexOf('}');
  if (a === -1 || b <= a) return null;
  s = s.substring(a, b + 1);
  try { return JSON.parse(s); } catch (e) { /* try repair below */ }
  try {
    const repaired = s
      .replace(/'([^'\\]*(?:\\.[^'\\]*)*)'/g, '"$1"')                       // single -> double quotes
      .replace(/([{,]\s*[\r\n\t]*)([a-zA-Z0-9_]+)(\s*[\r\n\t]*):/g, '$1"$2"$3:') // quote bare keys
      .replace(/,\s*([}\]])/g, '$1');                                        // trailing commas
    return JSON.parse(repaired);
  } catch (e) { return null; }
};

const ex = $('Extract Files').first().json;
const coreRaw = $('Call LLM').first().json;
const extRaw = $input.first().json;

const coreParsed = parseJson(extractText(coreRaw));
const extParsed = parseJson(extractText(extRaw));

const notes = [];
if (!coreParsed) notes.push('Core report: the model output could not be parsed, so placeholder content is shown. Re-run, or raise max_tokens and the llama-server context size.');
if (!extParsed) notes.push('Extended analysis (price and whitespace, trends, buyer factors, messaging gaps) is unavailable: the second model call failed or returned invalid JSON.');
if (ex.p2_truncated || ex.p3_truncated) notes.push('One or more reports were longer than the extraction limit and were truncated before analysis.');
if ((ex.p2_chars || 0) < 200 || (ex.p3_chars || 0) < 200) notes.push('A report produced very little text. Check that the right HTML files were uploaded for P2 and P3.');

const core = coreParsed || FALLBACK;
const ext = extParsed || {};

const content = { ...core };
['price_whitespace', 'trend_outlook', 'buyer_decision_factors', 'messaging_gaps', 'conflicts_caveats'].forEach(k => {
  content[k] = arr(ext[k]);
});

// Normalize list fields so Build HTML never receives a non-array
content.key_metrics = arr(content.key_metrics).filter(m => m && m.value !== undefined && m.value !== null && m.value !== '');
content.content_ideas = arr(content.content_ideas);
content.campaigns = arr(content.campaigns);
content.email_subjects = arr(content.email_subjects);
content.competitive_angles = arr(content.competitive_angles);
content.content_priorities = arr(content.content_priorities);
const df = content.data_foundation && typeof content.data_foundation === 'object' ? content.data_foundation : {};
content.data_foundation = { p2_insights: arr(df.p2_insights), p3_insights: arr(df.p3_insights) };
const sc = content.social_captions && typeof content.social_captions === 'object' ? content.social_captions : {};
content.social_captions = { instagram: arr(sc.instagram), pinterest: arr(sc.pinterest), facebook: arr(sc.facebook), tiktok: arr(sc.tiktok) };

content.run_notes = notes;
content.category = content.category || ex.category || 'Outdoor Rug';
content.focus = content.focus !== undefined ? content.focus : (ex.focus || '');

return { json: content };

// Grab data from Parse Content, but also look back at Extract Files for category/focus if needed
const c = $input.first().json;

// Pull category/focus from upstream nodes if they aren't embedded in the LLM response
const category = c.category || $('Extract Files').first().json.category || 'Area Rug';

const focus = c.focus !== undefined ? c.focus : ($('Extract Files').first().json.focus || '');



const today = new Date().toLocaleDateString('en-US', {year: 'numeric', month: 'long', day: 'numeric'});
const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Key Metrics Cards
const metrics = c.key_metrics || [];
let metricsHtml = metrics.map(m => `
  <div class="insight-card">
    <div class="number">${esc(m.value)}</div>
    <div class="label">${esc(m.label)}${m.source ? ' · ' + esc(m.source) : ''}</div>
  </div>
`).join('');

// Data Foundation
const df = c.data_foundation || {};
let p2List = (df.p2_insights || []).map(i => `<li>${esc(i)}</li>`).join('');
let p3List = (df.p3_insights || []).map(i => `<li>${esc(i)}</li>`).join('');

// Content Ideas
const ideas = c.content_ideas || [];
let ideasHtml = ideas.map(i => {
  const kws = (i.seo_keywords || []).map(k => `<span class="keyword">${esc(k)}</span>`).join('');
  return `
  <div class="content-card">
    <div class="content-card-header">
      <div class="type">${esc(i.type)}</div>
      <h4>${esc(i.title)}</h4>
    </div>
    <div class="content-card-body">
      <p>${esc(i.description)}</p>
      <div class="data-tag">📊 ${esc(i.data_connection)}</div>
      ${kws ? `<div class="keywords">${kws}</div>` : ''}
    </div>
  </div>`;
}).join('');

// Social Captions
const soc = c.social_captions || {};
let igHtml = (soc.instagram || []).map(p => `
  <div class="social-post">
    <div class="platform-badge ig">Instagram</div>
    <p>${esc(p.caption)}</p>
    <div class="hashtags">${(p.hashtags || []).join(' ')}</div>
  </div>
`).join('');
let pinHtml = (soc.pinterest || []).map(p => `
  <div class="social-post">
    <div class="platform-badge pin">Pinterest</div>
    <p><strong>${esc(p.title)}</strong></p>
    <p>${esc(p.description)}</p>
  </div>
`).join('');
let fbHtml = (soc.facebook || []).map(p => `
  <div class="social-post">
    <div class="platform-badge fb">Facebook</div>
    <p>${esc(p.post)}</p>
  </div>
`).join('');
let ttHtml = (soc.tiktok || []).map(p => `
  <div class="social-post">
    <div class="platform-badge tt">TikTok</div>
    <p><strong>Hook:</strong> ${esc(p.hook)}</p>
    <p>${esc(p.script)}</p>
  </div>
`).join('');

// Campaigns
const camps = c.campaigns || [];
let campsHtml = camps.map(camp => {
  const det = camp.details || {};
  let detailsHtml = Object.entries(det).map(([k, v]) => `
    <div class="campaign-detail">
      <h5>${k.replace(/_/g, ' ').replace(/\b\w/g, ch => ch.toUpperCase())}</h5>
      <p>${esc(v)}</p>
    </div>
  `).join('');
  return `
  <div class="campaign-card">
    <h4>Campaign: "${esc(camp.name)}"</h4>
    <div class="tagline">"${esc(camp.tagline)}"</div>
    <p>${esc(camp.description)}</p>
    <div class="campaign-details">${detailsHtml}</div>
  </div>`;
}).join('');

// Email Subjects
const emails = c.email_subjects || [];
let emailsHtml = emails.map(e => {
  const rateClass = e.open_rate === 'high' ? 'high' : 'medium';
  return `
  <div class="email-subject">
    <span class="icon">${e.icon || '📧'}</span>
    <span class="subject-text">${esc(e.subject)}</span>
    ${e.open_rate ? `<span class="open-rate ${rateClass}">Est. ${e.open_rate === 'high' ? 'High' : 'Medium'} Open</span>` : ''}
  </div>`;
}).join('');

// Competitive Angles
const angles = c.competitive_angles || [];
let anglesHtml = angles.map(a => `
  <div class="competitive-angle">
    <h4>Angle: "${esc(a.title)}"</h4>
    <p><strong>Competitor Gap:</strong> ${esc(a.competitor_gap)}</p>
    <p><strong>Wayfair Opportunity:</strong> ${esc(a.wayfair_opportunity)}</p>
  </div>
`).join('');

// Content Priorities
const priorities = c.content_priorities || [];
let prioritiesHtml = priorities.map(p => {
  const prioClass = p.priority <= 2 ? 'high' : 'medium';
  return `
  <div class="recommendation">
    <div class="priority ${prioClass}">${p.priority}</div>
    <div class="recommendation-content">
      <h4>${esc(p.title)}</h4>
      <p>${esc(p.rationale)}</p>
    </div>
  </div>`;
}).join('');

// ---- Extended sections (second LLM call) ----
const fieldRows = (r, fields) => fields
  .map(([k, label]) => (r && r[k] ? `<p><strong>${label}:</strong> ${esc(r[k])}</p>` : ''))
  .join('');

const cardGrid = (title, rows, fields, tagFn) => {
  const list = Array.isArray(rows) ? rows.filter(r => r && typeof r === 'object') : [];
  if (!list.length) return '';
  return `
    <section class="section">
      <h2>${title}</h2>
      <div class="content-grid">${list.map(r => `
        <div class="content-card"><div class="content-card-body">
          ${tagFn ? tagFn(r) : ''}
          ${fieldRows(r, fields)}
          ${r.source_ref ? `<div class="src-ref">📎 ${esc(r.source_ref)}</div>` : ''}
        </div></div>`).join('')}
      </div>
    </section>`;
};

const confTag = r => {
  if (!r.confidence) return '';
  const reported = String(r.confidence).toLowerCase().includes('reported');
  return `<div class="data-tag ${reported ? 'conf-reported' : 'conf-inferred'}">${reported ? 'Reported' : 'Inferred'}</div>`;
};

const priceWhitespaceHtml = cardGrid('💲 Price & Whitespace Opportunities', c.price_whitespace,
  [['opportunity', 'Opportunity'], ['price_band', 'Price band'], ['evidence', 'Evidence'], ['content_angle', 'Content angle']]);
const trendHtml = cardGrid('📈 Trend Outlook', c.trend_outlook,
  [['trend', 'Trend'], ['evidence', 'Evidence'], ['content_implication', 'What to publish']], confTag);
const buyerHtml = cardGrid('🛒 Buyer Decision Factors', c.buyer_decision_factors,
  [['factor', 'Factor'], ['why_it_matters', 'Why it matters'], ['content_angle', 'Content angle']]);
const messagingHtml = cardGrid('🗣️ Competitor Messaging Gaps', c.messaging_gaps,
  [['competitor_claim', 'Competitors emphasize'], ['opening', 'Opening for Wayfair'], ['content_angle', 'Content angle']]);

const caveatList = (Array.isArray(c.conflicts_caveats) ? c.conflicts_caveats : []).filter(Boolean);
const runNotes = (Array.isArray(c.run_notes) ? c.run_notes : []).filter(Boolean);
const li = x => `<li>${esc(typeof x === 'string' ? x : JSON.stringify(x))}</li>`;
const caveatsHtml = (caveatList.length || runNotes.length) ? `
    <section class="section caveats">
      <h2>⚠️ Conflicts & Caveats</h2>
      ${caveatList.length ? `<ul>${caveatList.map(li).join('')}</ul>` : ''}
      ${runNotes.length ? `<h4>Run notes</h4><ul>${runNotes.map(li).join('')}</ul>` : ''}
    </section>` : '';

const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>AI Insights & Content Report | Wayfair ${esc(category)}</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; line-height: 1.6; color: #333; background: #f8f9fa; }
    .container { max-width: 1100px; margin: 0 auto; padding: 20px; }
    .header { background: linear-gradient(135deg, #7B2D8E 0%, #5E1A6E 100%); color: white; padding: 40px; border-radius: 12px; margin-bottom: 30px; }
    .header h1 { font-size: 2.2em; margin-bottom: 10px; }
    .header .subtitle { font-size: 1.2em; opacity: 0.9; }
    .header .meta { margin-top: 20px; display: flex; gap: 15px; flex-wrap: wrap; }
    .header .meta-item { background: rgba(255,255,255,0.15); padding: 8px 16px; border-radius: 20px; font-size: 0.9em; }
    .section { background: white; border-radius: 12px; padding: 30px; margin-bottom: 25px; box-shadow: 0 2px 8px rgba(0,0,0,0.08); }
    .section h2 { color: #7B2D8E; font-size: 1.5em; margin-bottom: 20px; padding-bottom: 10px; border-bottom: 2px solid #f0e6f4; }
    .exec-summary { background: linear-gradient(135deg, #f8f4fa 0%, #fff 100%); border-left: 4px solid #7B2D8E; }
    .exec-summary p { font-size: 1.05em; margin-bottom: 15px; white-space: pre-line; }
    .key-insights { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 15px; margin-top: 20px; }
    .insight-card { background: white; border: 1px solid #e0d4e6; border-radius: 8px; padding: 20px; text-align: center; }
    .insight-card .number { font-size: 2.2em; font-weight: bold; color: #7B2D8E; }
    .insight-card .label { font-size: 0.85em; color: #666; margin-top: 5px; }
    .data-sources { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
    .data-source-card { background: #f8f9fa; border-radius: 8px; padding: 20px; }
    .data-source-card h4 { color: #7B2D8E; margin-bottom: 12px; }
    .data-source-card ul { list-style: none; padding-left: 0; }
    .data-source-card li { padding: 8px 0; border-bottom: 1px solid #e9ecef; font-size: 0.95em; }
    .content-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 20px; }
    .content-card { background: #fff; border: 1px solid #e0e0e0; border-radius: 10px; overflow: hidden; }
    .content-card-header { background: linear-gradient(135deg, #7B2D8E 0%, #9B4DB8 100%); color: white; padding: 15px 20px; }
    .content-card-body { padding: 20px; }
    .data-tag { display: inline-block; background: #f0e6f4; color: #7B2D8E; padding: 6px 12px; border-radius: 15px; font-size: 0.85em; margin-bottom: 10px; }
    .social-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 15px; }
    .social-post { background: #f8f9fa; border-radius: 8px; padding: 15px; }
    .platform-badge { display: inline-block; padding: 4px 10px; border-radius: 12px; font-size: 0.75em; font-weight: 600; color: white; margin-bottom: 10px; }
    .platform-badge.ig { background: linear-gradient(45deg, #f09433, #dc2743); }
    .platform-badge.pin { background: #E60023; }
    .platform-badge.fb { background: #1877F2; }
    .platform-badge.tt { background: #000; }
    .campaign-card { background: linear-gradient(135deg, #f8f4fa 0%, #fff 100%); border: 1px solid #e0d4e6; border-radius: 10px; padding: 25px; margin-bottom: 20px; }
    .campaign-details { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 15px; }
    .campaign-detail { background: white; padding: 15px; border-radius: 8px; }
    .email-ideas { display: flex; flex-direction: column; gap: 10px; }
    .email-subject { display: flex; align-items: center; gap: 15px; background: #f8f9fa; padding: 15px 20px; border-radius: 8px; }
    .email-subject .open-rate { background: #e0f2e9; color: #059669; padding: 5px 12px; border-radius: 15px; font-size: 0.8em; }
    .competitive-angle { background: #f8f9fa; border-left: 4px solid #7B2D8E; padding: 20px; margin-bottom: 15px; }
    .recommendation { display: flex; gap: 20px; margin-bottom: 15px; align-items: flex-start; }
    .priority { width: 40px; height: 40px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: bold; color: white; flex-shrink: 0; background: #7B2D8E; }
    .recommendation-content { flex: 1; background: #f8f9fa; padding: 15px 20px; border-radius: 8px; }
    .footer { background: #5E1A6E; color: white; padding: 30px; border-radius: 12px; text-align: center; margin-top: 30px; }
    .src-ref { font-size: 0.8em; color: #7B2D8E; margin-top: 10px; }
    .data-tag.conf-reported { background: #e0f2e9; color: #059669; }
    .data-tag.conf-inferred { background: #fff4d6; color: #9a6700; }
    .content-card-body p { margin-bottom: 8px; }
    .caveats { background: #fffaf0; border-left: 4px solid #f0a500; }
    .caveats ul { padding-left: 20px; margin-bottom: 12px; }
    .caveats li { margin-bottom: 6px; }
    .caveats h4 { margin: 12px 0 6px; color: #9a6700; }
  </style>
</head>
<body>
  <div class="container">
    <header class="header">
      <h1>AI Insights & Content Report</h1>
      <p class="subtitle">Wayfair ${esc(category)}${focus ? ' - ' + esc(focus) : ''}</p>
      <div class="meta">
        <span class="meta-item">📅 ${today}</span>
        <span class="meta-item">📊 ${metrics.length} Key Data Points</span>
        <span class="meta-item">💡 ${ideas.length} Content Ideas</span>
        <span class="meta-item">🎯 ${camps.length} Campaigns</span>
      </div>
    </header>

    <section class="section exec-summary">
      <h2>📋 Executive Summary</h2>
      <p>${esc(c.executive_summary || '')}</p>
      <div class="key-insights">${metricsHtml}</div>
    </section>

    <section class="section">
      <h2>📊 Data Foundation</h2>
      <p>Key insights extracted from your reports:</p>
      <div class="data-sources">
        <div class="data-source-card">
          <h4>📈 From Market Analysis (P2)</h4>
          <ul>${p2List}</ul>
        </div>
        <div class="data-source-card">
          <h4>🔍 From Competitor Analysis (P3)</h4>
          <ul>${p3List}</ul>
        </div>
      </div>
    </section>

    ${priceWhitespaceHtml}
    ${trendHtml}
    ${buyerHtml}

    <section class="section">
      <h2>💡 Content Ideas</h2>
      <div class="content-grid">${ideasHtml}</div>
    </section>

    <section class="section">
      <h2>📱 Social Media Captions</h2>
      <div class="social-grid">${igHtml}${pinHtml}${fbHtml}${ttHtml}</div>
    </section>

    <section class="section">
      <h2>🎯 Campaign Concepts</h2>
      ${campsHtml}
    </section>

    <section class="section">
      <h2>📧 Email Subject Lines</h2>
      <div class="email-ideas">${emailsHtml}</div>
    </section>

    <section class="section">
      <h2>⚔️ Competitive Content Angles</h2>
      ${anglesHtml}
    </section>

    ${messagingHtml}

    <section class="section">
      <h2>📅 Recommended Content Priorities</h2>
      ${prioritiesHtml}
    </section>

    ${caveatsHtml}

    <footer class="footer">
      <div class="logo">Wayfair | AI Insights & Content Agent</div>
      <p>Category: ${esc(category)}${focus ? ' | Focus: ' + esc(focus) : ''} | Date: ${today}</p>
    </footer>
  </div>
</body>
</html>`;

return [{json: {html, category, focus}}];

const html = $input.first().json.html;
const cat = $input.first().json.category || 'Area Rug';
const ts = new Date().toISOString().split('T')[0];
const fileName = `Wayfair_${cat.replace(/\s+/g, '_')}_Content_Strategy_${ts}.html`;

return [{
  json: { html, fileName },
  binary: {
    data: {
      data: Buffer.from(html).toString('base64'),
      mimeType: 'text/html',
      fileName: fileName
    }
  }
}];

const item = $input.first().json;

const systemPrompt = `You are a senior content strategist for Wayfair. Analyze the market (P2) and competitor (P3) reports below and write a content strategy report.

